args<-commandArgs(TRUE);o<-if(length(args))args[1]else'.'
source(file.path(o,'cell_type_labels.R'))
eq<-read.csv(file.path(o,'supplementary_tables/S5_eqtl_summary.csv'))
cols<-c(GAM6='#0072B2',contribution='#D55E00',expected_count='#009E73')
fig<-function(name,w,h,fun){for(ext in c('pdf','png')){f<-file.path(o,'figures',paste0(name,'.',ext));if(ext=='pdf')pdf(f,width=w,height=h,family='Helvetica',useDingbats=FALSE)else png(f,width=w,height=h,units='in',res=300,type='cairo');par(mar=c(4.4,4.5,2.8,1),mgp=c(2.7,.8,0),las=1,cex=.9);fun();dev.off()}}
fig('Figure_S11_eqtl',10,6,function(){par(mfrow=c(2,3));for(metric in c('detection_rate','pooled_FDP'))for(ct in c('Excit','Inhib','Oligo')){plot(NA,xlim=c(.45,.85),ylim=c(0,100),xaxt='n',xlab='Injected signal ratio',ylab=if(metric=='detection_rate')'Injected effects detected (%)'else'Pooled FDP (%)',main=ct_name(ct),cex.main=.9);axis(1,c(.5,.8));for(m in c('GAM6','contribution','expected_count')){d<-subset(eq,engine=='CDSeq2'&cell_type==ct&score_scope=='scenario'&method==m&policy=='matched_tested_budget'&group=='top40'&pattern=='all'&signal_ratio>0);d<-d[order(d$signal_ratio),];stopifnot(nrow(d)==2);lines(d$signal_ratio,d[[metric]]*100,type='b',pch=16,col=cols[m],lwd=2)};d<-subset(eq,engine=='CDSeq2'&cell_type==ct&score_scope=='scenario'&method=='GAM6'&policy=='full_panel'&group=='all'&pattern=='all'&signal_ratio>0);lines(d$signal_ratio,d[[metric]]*100,type='b',pch=15,col='#555555',lty=2);if(ct=='Oligo'&&metric=='pooled_FDP')legend('topleft',c('CDSeq2 (with gene-type prioritization)','Contribution ranking','Expected-count ranking','CDSeq2 (without gene-type prioritization)'),col=c(cols[c('GAM6','contribution','expected_count')],'#555555'),lty=c(1,1,1,2),bty='n',cex=.58)}})
